// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadLora = makeLoadFont('Lora');
const loadInter = makeLoadFont('Inter');

const { fontFamily: stampFontFamily } = loadOswald();
const { fontFamily: documentFontFamily } = loadLora();
const { fontFamily: bubbleFontFamily } = loadInter();



export type CinematicPoliticalGraphicProps = Record<string, any>;

const CinematicPoliticalGraphic: React.FC<CinematicPoliticalGraphicProps> = ({
  backgroundColor = "#070000",
  transparentBackground = false,
  durationInSeconds = 10,
  planTitle = "15-POINT PLAN",
  stampText = "REJECTED",
  speechText = "NO",
  glowColor = "#e50000",
  stampColor = "#cc0000",
  sparkCount = 120,
  intensity = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Basic Setup
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;
  
  // Timing variables
  const docEnterFrame = 10;
  const slamImpactFrame = 45;
  const bubbleStartFrame = 55;

  // -- ANIMATIONS --

  // 1. Camera Shake (triggered on stamp impact)
  const shakeAmount = interpolate(
    frame,
    [slamImpactFrame, slamImpactFrame + 15],
    [30 * intensity, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const shakeX = shakeAmount > 0 ? shakeAmount * Math.sin(frame * 2.5) : 0;
  const shakeY = shakeAmount > 0 ? shakeAmount * Math.cos(frame * 2.1) : 0;

  // 2. Document Entrance
  const docEnterProgress = spring({
    frame: frame - docEnterFrame,
    fps,
    config: { damping: 14, stiffness: 80, mass: 1.5 },
  });
  const docY = interpolate(docEnterProgress, [0, 1], [height * 0.8, 0]);
  const docRotate = interpolate(docEnterProgress, [0, 1], [-15, -3]);
  const docScale = interpolate(docEnterProgress, [0, 1], [0.8, 1]);

  // 3. Stamp Entrance
  const rawStampScale = spring({
    frame: frame - slamImpactFrame,
    fps,
    config: { damping: 12, stiffness: 250, mass: 1 },
  });
  const stampScale = interpolate(rawStampScale, [0, 1], [6, 1], { extrapolateRight: "clamp" });
  const stampOpacity = interpolate(frame, [slamImpactFrame, slamImpactFrame + 2], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const stampRotate = interpolate(rawStampScale, [0, 1], [20, -10]);

  // 4. Background Pulses
  const bgPulse = (Math.sin(frame * 0.05) + 1) / 2; // 0 to 1
  const glowOpacity = 0.3 + bgPulse * 0.4 * intensity;

  // Configuration for Document Mock Lines
  const documentLines = new Array(9).fill(0);

  // Configuration for Speech Bubbles
  const bubbleConfigs = [
    { x: 0.1, y: 0.25, rot: -18, delay: 0 },
    { x: 0.75, y: 0.15, rot: 12, delay: 5 },
    { x: 0.82, y: 0.65, rot: -8, delay: 10 },
    { x: 0.08, y: 0.75, rot: 22, delay: 15 },
    { x: 0.65, y: 0.85, rot: -15, delay: 20 },
    { x: 0.2, y: 0.1, rot: 8, delay: 25 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* BACKGROUND LAYER: Abstract Iranian Flag Colors with Heavy Dark Red Tint */}
      <AbsoluteFill style={{ opacity: 0.15, filter: "blur(30px) saturate(2)" }}>
        <div style={{ flex: 1, backgroundColor: "#239f40", transform: "scale(1.2) rotate(-5deg)" }} />
        <div style={{ flex: 1, backgroundColor: "#ffffff", transform: "scale(1.2) rotate(-5deg)" }} />
        <div style={{ flex: 1, backgroundColor: "#da0000", transform: "scale(1.2) rotate(-5deg)" }} />
      </AbsoluteFill>

      {/* GLOW LAYER */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, ${glowColor}${Math.floor(glowOpacity * 255).toString(16).padStart(2, "0")} 0%, transparent 80%)`,
          mixBlendMode: "screen",
        }}
      />

      {/* PARTICLES / SPARKS LAYER */}
      <AbsoluteFill style={{ transition: "none" }}>
        {new Array(sparkCount).fill(0).map((_, i) => {
          const startX = random(`spark-x-${i}`) * width;
          const speed = 2 + random(`spark-speed-${i}`) * 6 * intensity;
          const delay = random(`spark-delay-${i}`) * 500;
          const size = 2 + random(`spark-size-${i}`) * 8;
          
          // Continuous flowing logic (0 to 1 cycle)
          const cycleHeight = height + 200;
          const progress = ((frame * speed + delay) % cycleHeight) / cycleHeight;
          
          // Starts from bottom (1) goes to top (0)
          const yPos = cycleHeight - (progress * cycleHeight) - 100;
          const sway = Math.sin((frame + delay) * 0.05) * 40;
          const opacity = Math.sin(progress * Math.PI) * 0.8;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: startX + sway,
                top: yPos,
                width: size,
                height: size,
                backgroundColor: i % 3 === 0 ? "#ffffff" : "#ffaa00",
                borderRadius: "50%",
                opacity: opacity,
                boxShadow: `0 0 ${size * 2}px ${glowColor}`,
                filter: "blur(1px)",
                transition: "none",
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* MAIN CONTENT COMPOSITION (With Camera Shake) */}
      <AbsoluteFill
        style={{
          transform: `translate(${shakeX}px, ${shakeY}px)`,
          transition: "none",
        }}
      >
        {/* DOCUMENT */}
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            transform: `translateY(${docY}px) rotate(${docRotate}deg) scale(${docScale})`,
            transition: "none",
          }}
        >
          <div
            style={{
              width: width * 0.85,
              height: height * 0.65,
              backgroundColor: "#f4f1ea", // Aged paper off-white
              borderRadius: 8,
              boxShadow: `0 30px 60px rgba(0,0,0,0.8), inset 0 0 100px rgba(0,0,0,0.1), 0 0 50px ${glowColor}40`,
              padding: "80px 60px",
              display: "flex",
              flexDirection: "column",
              position: "relative",
              overflow: "hidden",
            }}
          >
            {/* Paper Texture Overlay (Simulated via gradient noise) */}
            <div
              style={{
                position: "absolute",
                top: 0, left: 0, right: 0, bottom: 0,
                background: "repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.02) 2px, rgba(0,0,0,0.02) 4px)",
                pointerEvents: "none",
              }}
            />

            {/* Document Header */}
            <h1
              style={{
                fontFamily: documentFontFamily,
                fontSize: 64,
                fontWeight: 800,
                color: "#1a1a1a",
                textAlign: "center",
                margin: "0 0 60px 0",
                textTransform: "uppercase",
                letterSpacing: "4px",
                borderBottom: "4px solid #1a1a1a",
                paddingBottom: 20,
              }}
            >
              {planTitle}
            </h1>

            {/* Document Mock Content */}
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 30 }}>
              {documentLines.map((_, i) => (
                <div
                  key={i}
                  style={{
                    height: 12,
                    backgroundColor: "#d0ccc0",
                    width: i === documentLines.length - 1 ? "60%" : "100%",
                    borderRadius: 6,
                  }}
                />
              ))}
              <div style={{ marginTop: 40, display: "flex", gap: 30 }}>
                 <div style={{ height: 12, backgroundColor: "#d0ccc0", width: "40%", borderRadius: 6 }} />
                 <div style={{ height: 12, backgroundColor: "#d0ccc0", width: "30%", borderRadius: 6 }} />
              </div>
            </div>

            {/* REJECTED STAMP */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: `translate(-50%, -50%) scale(${stampScale}) rotate(${stampRotate}deg)`,
                opacity: stampOpacity,
                border: `14px solid ${stampColor}`,
                padding: "20px 40px",
                borderRadius: 16,
                color: stampColor,
                fontFamily: stampFontFamily,
                fontSize: 120,
                fontWeight: 900,
                letterSpacing: "8px",
                textTransform: "uppercase",
                boxShadow: `0 0 40px ${stampColor}66, inset 0 0 20px ${stampColor}40`,
                textShadow: `0 0 10px ${stampColor}80`,
                mixBlendMode: "multiply", // Makes it look printed on the paper
                transition: "none",
              }}
            >
              {stampText}
              {/* Fake distressed texture on stamp via pseudo-elements is hard in React inline,
                  so we use a subtle radial gradient mask if supported, or just keep it solid for stability */}
            </div>
          </div>
        </AbsoluteFill>

        {/* SPEECH BUBBLES */}
        <AbsoluteFill>
          {bubbleConfigs.map((config, i) => {
            const bFrame = frame - (bubbleStartFrame + config.delay);
            const bSpring = spring({
              frame: bFrame,
              fps,
              config: { damping: 10, stiffness: 200, mass: 0.8 },
            });
            const bScale = interpolate(bSpring, [0, 1], [0, 1], { extrapolateRight: "clamp" });
            const bOpacity = interpolate(bFrame, [0, 5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

            if (bFrame < 0) return null;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: width * config.x,
                  top: height * config.y,
                  transform: `translate(-50%, -50%) rotate(${config.rot}deg) scale(${bScale})`,
                  opacity: bOpacity,
                  transition: "none",
                }}
              >
                {/* Bubble Body */}
                <div
                  style={{
                    backgroundColor: "#111111",
                    border: `6px solid ${glowColor}`,
                    padding: "20px 40px",
                    borderRadius: 24,
                    boxShadow: `0 15px 30px rgba(0,0,0,0.8), 0 0 30px ${glowColor}66`,
                    position: "relative",
                  }}
                >
                  <span
                    style={{
                      fontFamily: bubbleFontFamily,
                      fontSize: 80,
                      fontWeight: 900,
                      color: "#ffffff",
                      letterSpacing: "2px",
                      textShadow: "0 4px 10px rgba(0,0,0,0.8)",
                    }}
                  >
                    {speechText}
                  </span>
                  {/* Bubble Tail */}
                  <div
                    style={{
                      position: "absolute",
                      bottom: -25,
                      left: "50%",
                      transform: "translateX(-50%)",
                      width: 0,
                      height: 0,
                      borderLeft: "20px solid transparent",
                      borderRight: "20px solid transparent",
                      borderTop: `25px solid ${glowColor}`,
                    }}
                  />
                  <div
                    style={{
                      position: "absolute",
                      bottom: -18,
                      left: "50%",
                      transform: "translateX(-50%)",
                      width: 0,
                      height: 0,
                      borderLeft: "14px solid transparent",
                      borderRight: "14px solid transparent",
                      borderTop: `18px solid #111111`,
                      zIndex: 2,
                    }}
                  />
                </div>
              </div>
            );
          })}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* FOREGROUND VIGNETTE FOR DRAMA & CONTRAST */}
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle, transparent 30%, rgba(0,0,0,0.8) 100%)",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default CinematicPoliticalGraphic;